import fs from 'node:fs';
import path from 'node:path';
import { storePaths } from './src/store.mjs';

const dir = storePaths().dir;
const tgOps = '6644482344';

function readJsonl(p, max=5000) {
  if (!fs.existsSync(p)) return [];
  return fs.readFileSync(p,'utf8').split(/\r?\n/).filter(Boolean).map(l=>{try{return JSON.parse(l)}catch{return null}}).filter(Boolean);
}

function isTg(o) {
  const s = JSON.stringify(o);
  return s.includes('telegram') || s.includes(tgOps) || s.includes('tg:');
}

const inbound = readJsonl(path.join(dir,'logs','inbound.jsonl'));
const outbound = readJsonl(path.join(dir,'logs','outbound.jsonl'));
const utterances = readJsonl(path.join(dir,'training','utterances.jsonl'));
const actions = readJsonl(path.join(dir,'logs','actions.jsonl'));

const inHit = inbound.filter(isTg);
const outHit = outbound.filter(isTg);
const uttHit = utterances.filter(isTg);
const actHit = actions.filter(a => isTg(a) && (a.type==='ava.utterance' || a.type==='ask' || String(a.type||'').includes('telegram')));

console.log('inbound tg', inHit.length);
for (const x of inHit.slice(-30)) console.log(JSON.stringify(x).slice(0,600));
console.log('\\noutbound tg', outHit.length);
for (const x of outHit.slice(-30)) console.log(JSON.stringify(x).slice(0,600));
console.log('\\nutterances tg', uttHit.length);
for (const x of uttHit.slice(-30)) console.log(JSON.stringify(x).slice(0,800));
console.log('\\nactions recent tg', actHit.length);
for (const x of actHit.slice(-40)) console.log(JSON.stringify(x).slice(0,500));
"

